        print(-1)
        return

    visited = [False] * (N + 1)
    parent = [0] * (N + 1)
    down = [0] * (N + 1)
    best = 0

    for start in range(1, N + 1):
        if not good[start] or visited[start]:
            continue

        order = []
        stack = [start]
        visited[start] = True
        parent[start] = 0
        while stack:
            u = stack.pop()
            order.append(u)
            for v in adj[u]:
                if good[v] and not visited[v]:
                    visited[v] = True
                    parent[v] = u
                    stack.append(v)

        for u in reversed(order):
            child_downs = []
            p = parent[u]
            for v in adj[u]:
                if good[v] and v != p:
                    child_downs.append(down[v])
            child_downs.sort(reverse=True)
            down[u] = 1 + sum(child_downs[:3])
            cand = 1 + sum(child_downs[:4])
            if cand > best:
                best = cand

    if best == 0:
        print(-1)
    else:
        print(3 * best + 2)

